inherit ROOM; void create(){ set("short","悬崖"); set("long","这里是陡峭的悬崖，岩壁几乎直上直下，只能靠手脚攀爬寻找出路，可以试著向上或向下攀爬(climb up/down)。\n"); set("map/area","老松林"); set("map/layer","谷壁"); setup(); } void init(){ add_action("do_climb","climb"); } int do_climb(string arg){ if(arg=="up"){ this_player()->move(__DIR__"cliffside"); return 1;} if(arg=="down"){ this_player()->move(__DIR__"riverbank1"); return 1;} return notify_fail("你要往上还是往下爬？\n"); }